  pronuncia: [
    { regra: "LL e Y soam como \"ch\" de \"chave\" (aqui escrito \"sh\")", ex: "calle → KA-she · yo → SHO · lluvia → SHU-bia", dica: "É a marca do sotaque uruguaio e argentino." },
    { regra: "J (e G antes de E/I) é um \"rr\" soprado, como em \"carro\"", ex: "jamón → rra-MON · gente → RREN-te" },
    { regra: "R inicial e RR vibram na ponta da língua", ex: "rambla → RRAM-bla · perro → PE-rro", dica: "Na pronúncia escrita, os dois sons aparecem como \"rr\". Olhe o espanhol: se for R, vibre; se for J ou G, sopre." },
    { regra: "V tem som de B, e o H é sempre mudo", ex: "vino → BI-no · vos → BOS · hola → O-la · hielo → IE-lo" },
    { regra: "Z, C (antes de E/I) e S soam como o S de \"sapo\"", ex: "cerveza → ser-BE-sa · cinco → SIN-ko · mesa → ME-sa (não \"meza\")" },
    { regra: "Ñ = NH e CH = TCH", ex: "baño → BA-nho · mañana → ma-NHA-na · leche → LE-tche" },
    { regra: "Não anasale as vogais", ex: "pan → PAN (não \"pã\") · bien → BIEN", dica: "Fale \"pan\" com o N bem marcado, sem soar como \"pão\"." },
    { regra: "E e O finais não viram I e U; T e D não chiam", ex: "tarde → TAR-de (não \"tardji\") · vino → BI-no (não \"vinu\")" },
    { regra: "Use \"vos\" em vez de \"tú\"", ex: "vos tenés · vos podés · ¿vos querés?", dica: "A tônica vai pro final: te-NÉS, po-DÉS, ke-RÉS. Em Montevidéu, você também vai ouvir \"tú tenés\", e em partes de Maldonado e Rocha, o \"tú\" comum." },
  ],

